package run.ikaros.sharing; import java.util.UUID; import org.springframework.data.repository.reactive.ReactiveCrudRepository; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono; public interface ShareRepository extends ReactiveCrudRepository<ShareEntity,UUID>{Flux<ShareEntity> findAllByIssuerIdOrderByCreatedAtDesc(UUID issuerId);Flux<ShareEntity> findAllByTargetTypeAndTargetId(String targetType,UUID targetId);Mono<ShareEntity> findByTokenDigest(String tokenDigest);}
